def _parse_members(text):
    """Parse member entries from a README section text.

    Returns list of dicts: {"name", "username", "line"}
    """
    member_re = re.compile(
        r'^[-*+] \[([^\]]+)\]\(https://github\.com/([^)]+)\)(?:,\s*(.+))?$',
        re.MULTILINE,
    )
    return [
        {
            "name": m.group(1),
            "username": m.group(2),
            "line": m.group(0),
        }
        for m in member_re.finditer(text)
    ]

def _parse_members(text, member_re=re.compile(
        r'^[-*+] \[([^\]]+)\]\(https://github\.com/([^)]+)\)(?:,\s*(.+))?$',
        re.MULTILINE,
    )):
    """Parse member entries from a README section text.

    Returns list of dicts: {"name", "username", "line"}
    """
    members = []
    for m in member_re.finditer(text):
        members.append({
            "name": m.group(1),
            "username": m.group(2),
            "line": m.group(0),
        })
    return members

